 $('stNext').textContent=nextLabel();$('stStageTitle').textContent=stageTitle();$('stReps').hidden=!['representations','mode'].includes(c);$('stPlaceValue').hidden=!isMean;$('stRecover').disabled=rep?s.representation==='raw-data':s.phase==='raw';
